import { tv, type VariantProps } from "@/lib/beton/tv";

export const descriptionList = tv({
  slots: {
    root: "w-full",
    group: "border-b-3 border-border last:border-b-0",
    term: "font-mono text-xs font-bold tracking-widest uppercase",
    description: "font-sans text-foreground",
  },
  variants: {
    layout: {
      stacked: {
        group: "flex flex-col gap-1 py-3 first:pt-0 last:pb-0",
      },
      inline: {
        group:
          "grid grid-cols-[minmax(8rem,12rem)_1fr] items-baseline gap-4 py-3 first:pt-0 last:pb-0",
      },
    },
    size: {
      sm: { description: "text-sm" },
      md: { description: "text-base" },
      lg: { description: "text-lg" },
    },
  },
  defaultVariants: {
    layout: "stacked",
    size: "md",
  },
});

export type DescriptionListVariants = VariantProps<typeof descriptionList>;

import { descriptionList, type DescriptionListVariants } from "@/lib/beton/recipes/description-list.recipe";
import type { ComponentProps, ReactNode } from "react";
import { renderElement, type RenderProp } from "@/lib/beton/render-element";

export interface DescriptionListProps extends ComponentProps<"dl">, DescriptionListVariants {
  render?: RenderProp;
}

function DescriptionListRoot({
  layout = "stacked",
  size = "md",
  className,
  render,
  ...props
}: DescriptionListProps) {
  const styles = descriptionList({ layout, size });
  return renderElement(
    "dl",
    { ...props, "data-layout": layout, className: styles.root({ class: className }) },
    render,
  );
}

export interface DescriptionListItemProps
  extends Omit<ComponentProps<"div">, "children">, DescriptionListVariants {
  /** The name of the field. */
  term: ReactNode;
  /** Its value. */
  children: ReactNode;
}

function DescriptionListItem({
  layout = "stacked",
  size = "md",
  term,
  children,
  className,
  ...props
}: DescriptionListItemProps) {
  const styles = descriptionList({ layout, size });
  return (
    <div {...props} className={styles.group({ class: className })}>
      <dt className={styles.term()}>{term}</dt>
      <dd className={styles.description()}>{children}</dd>
    </div>
  );
}

/** Pairs of terms and their values: metadata, receipts, specifications. */
export const DescriptionList = Object.assign(DescriptionListRoot, { Item: DescriptionListItem });
